# CRAN sae 1.3 independent reference. Inputs generated by sikov_validate.py.
args <- commandArgs(trailingOnly=TRUE)
if (length(args) != 2) stop("usage: sikov_sae_reference.R inputdir outputdir")
indir <- args[[1]]; outdir <- args[[2]]
lib <- normalizePath(file.path(dirname(dirname(indir)), "fuentes", "sae_library"),mustWork=FALSE)
# Explicit path supplied by caller through SIKOV_SAE_LIBRARY takes precedence.
lib <- Sys.getenv("SIKOV_SAE_LIBRARY",lib)
.libPaths(c(lib,.libPaths()))
suppressPackageStartupMessages(library(sae))
dir.create(outdir, recursive=TRUE, showWarnings=FALSE)
for (nm in c("knn4","knn6","knn8")) {
  dat <- read.csv(file.path(indir,paste0(nm,"_data.csv")))
  y <- dat$y; x <- dat$x; D <- dat$D
  W <- as.matrix(read.csv(file.path(indir,paste0(nm,"_W.csv")),header=FALSE))
  fit <- eblupSFH(y~x,vardir=D,proxmat=W,method="REML",MAXITER=1000,PRECISION=1e-9)
  fh <- eblupFH(y~x,vardir=D,method="REML",MAXITER=1000,PRECISION=1e-9)
  mse <- mseSFH(y~x,vardir=D,proxmat=W,method="REML",MAXITER=1000,PRECISION=1e-9)
  write.csv(data.frame(mean=as.vector(fit$eblup),mse=mse$mse,fhmean=as.vector(fh$eblup)),file.path(outdir,paste0(nm,"_pred.csv")),row.names=FALSE)
  write.csv(data.frame(A=fit$fit$refvar,rho=fit$fit$spatialcorr,converged=fit$fit$convergence,fhA=fh$fit$refvar),file.path(outdir,paste0(nm,"_param.csv")),row.names=FALSE)
}
writeLines(capture.output(sessionInfo()),file.path(outdir,"sessionInfo.txt"))
